CARDIO.register({"item":"d228","meta":{"num":"d228","label":"228","spe":"dermato","short":"Ulcère de jambe","title":"Ulcère de jambe","section":"D","chapter":18,"pages":"325-339","sdd":[{"num":83,"label":"Cicatrice anormale"},{"num":92,"label":"Ulcère cutané"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"}]},"objectives":[{"id":"d228-obj-01","rank":"A","rubric":"Définition","title":"Ulcère de jambe","desc":""},{"id":"d228-obj-02","rank":"A","rubric":"Diagnostic positif","title":"Savoir diagnostiquer un ulcère veineux, artériel, mixte","desc":"Identification des ulcères vasculaires"},{"id":"d228-obj-03","rank":"B","rubric":"Éléments physiopathologiques","title":"Connaître les principes physiopathologiques des ulcères de jambe artériels, veineux et mixtes","desc":""},{"id":"d228-obj-04","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître un ulcère veineux typique","desc":""},{"id":"d228-obj-05","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître un ulcère artériel typique","desc":""},{"id":"d228-obj-06","rank":"B","rubric":"Diagnostic positif","title":"Savoir diagnostiquer une angiodermite nécrotique","desc":""},{"id":"d228-obj-07","rank":"B","rubric":"Éléments physiopathologiques","title":"Connaître les bases physiopathologiques de l'angiodermite nécrotique","desc":"Artériolosclérose, HTA, diabète de type 2"},{"id":"d228-obj-08","rank":"B","rubric":"Contenu multimédia","title":"Reconnaître une angiodermite nécrotique","desc":""},{"id":"d228-obj-09","rank":"B","rubric":"Diagnostic positif","title":"Connaître les causes non vasculaires d'ulcères de jambe","desc":"Identifier les causes rares : neurotrophique, infectieuse, pyoderma gangrenosum, hémopathies, cancers cutanés, vascularite cutanée, médicamenteuse, pathomimie"},{"id":"d228-obj-10","rank":"A","rubric":"Prise en charge","title":"Connaître la compression et ses modalités","desc":"Connaître les différents types de contention"},{"id":"d228-obj-11","rank":"A","rubric":"Examens complémentaires","title":"Intérêt de l'imagerie : échographie Doppler artérioveineuse en première intention","desc":""},{"id":"d228-obj-12","rank":"B","rubric":"Examens complémentaires","title":"Savoir interpréter les pressions distales","desc":"Pour évaluer l'ischémie en cas d'ulcère artériel ou mixte"},{"id":"d228-obj-13","rank":"A","rubric":"Diagnostic positif","title":"Connaître les trois phases de cicatrisation d'un ulcère","desc":"Détersion, bourgeonnement, épidermisation"},{"id":"d228-obj-14","rank":"A","rubric":"Prise en charge","title":"Connaître les soins locaux, la gestion des exsudats, la détersion","desc":"Bourgeonnement et épithélialisation par moyens médicaux (connaître les différents types de pansements), greffes cutanées, traitement antalgique"},{"id":"d228-obj-15","rank":"A","rubric":"Suivi et/ou pronostic","title":"Connaître les complications des ulcères : allergies cutanées (eczéma de contact), infection et transformation maligne","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"d228-qroc-001","type":"QROC","rank":"A","objective":"d228-obj-01","tags":["définition"],"difficulty":1,"question":"Depuis combien de temps une plaie de la jambe doit-elle ne pas cicatriser pour parler d'ulcère de jambe ?","answer":"Plus d'un mois","accept":["1 mois","un mois","plus d'un mois"],"keywords":["un mois"],"explanation":"Un ulcère de jambe est une plaie de jambe qui ne cicatrise pas depuis plus d'un mois ; il complique une maladie vasculaire sous-jacente qui conditionne le pronostic et le traitement.","src":"p. 326"},{"id":"d228-qroc-002","type":"QROC","rank":"A","objective":"d228-obj-01","tags":["étiologie"],"difficulty":1,"question":"Par quelles deux maladies vasculaires la plupart des ulcères de jambe sont-ils causés ?","answer":"Insuffisance veineuse et artériopathie (AOMI)","accept":["insuffisance veineuse et AOMI","insuffisance veineuse et insuffisance artérielle","veineuse et artérielle"],"keywords":["veine","artér"],"explanation":"La plupart des ulcères sont de cause vasculaire, par insuffisance veineuse chronique ou artériopathie oblitérante des membres inférieurs ; les ulcères infectieux, neurotrophiques, dysimmunitaires et néoplasiques sont plus rares.","src":"p. 330, 338"},{"id":"d228-qroc-003","type":"QROC","rank":"A","objective":"d228-obj-04","tags":["épidémiologie","clinique"],"difficulty":1,"question":"Chez quel type de patient l'ulcère veineux est-il le plus fréquent ?","answer":"La femme de plus de 50 ans","accept":["femme","femme de plus de 50 ans"],"keywords":["femme"],"explanation":"L'ulcère veineux prédomine chez la femme de plus de 50 ans, avec un surpoids fréquent ; l'ulcère artériel touche plutôt l'homme de plus de 50 ans.","src":"p. 326, 329"},{"id":"d228-qroc-004","type":"QROC","rank":"A","objective":"d228-obj-05","tags":["épidémiologie","clinique"],"difficulty":1,"question":"Quel est le profil du patient typique de l'ulcère artériel (sexe, âge) ?","answer":"Un homme de plus de 50 ans","accept":["homme","homme de plus de 50 ans"],"keywords":["homme"],"explanation":"L'ulcère artériel touche surtout l'homme de plus de 50 ans, avec des facteurs de risque vasculaire : tabac, HTA, diabète, obésité, dyslipidémie.","src":"p. 329"},{"id":"d228-qroc-005","type":"QROC","rank":"A","objective":"d228-obj-04","tags":["clinique"],"difficulty":2,"question":"Où siège habituellement l'ulcère veineux ?","answer":"Région périmalléolaire, jusqu'au tiers inférieur du mollet","accept":["périmalléolaire","péri-malléolaire","malléolaire"],"keywords":["malléol"],"explanation":"L'ulcère veineux est en général unique, de grande taille, moyennement douloureux, de siège périmalléolaire (souvent interne) jusqu'au tiers inférieur du mollet.","src":"p. 327, 329"},{"id":"d228-qroc-006","type":"QROC","rank":"A","objective":"d228-obj-05","tags":["clinique"],"difficulty":2,"question":"Quelle topographie caractérise l'ulcère artériel ?","answer":"Suspendue ou distale (orteils)","accept":["distale","suspendue","orteils"],"keywords":["distal"],"explanation":"L'ulcère artériel est unique ou multiple, à l'emporte-pièce ou de grande taille, creusant (il peut mettre à nu les structures sous-jacentes), de topographie suspendue ou distale ; la douleur est habituellement intense.","src":"p. 329"},{"id":"d228-qroc-007","type":"QROC","rank":"A","objective":"d228-obj-05","tags":["clinique"],"difficulty":1,"question":"Quel est l'aspect de la peau péri-ulcéreuse dans l'ulcère artériel ?","answer":"Lisse, froide, dépilée","accept":["luisante froide dépilée","lisse froide dépilée"],"keywords":["froide","dépil"],"explanation":"Dans l'artériopathie, la peau est luisante et dépilée, avec baisse de la température cutanée ; on recherche aussi une pâleur à la surélévation, une cyanose de déclivité et un allongement du temps de recoloration pulpaire.","src":"p. 328-329"},{"id":"d228-qroc-008","type":"QROC","rank":"A","objective":"d228-obj-02","tags":["clinique","diagnostic"],"difficulty":2,"question":"Dans l'artériopathie, que devient la coloration du pied à la surélévation, puis en position déclive ?","answer":"Pâleur à la surélévation, cyanose de déclivité","accept":["pâleur puis cyanose","pâleur surélévation cyanose déclivité"],"keywords":["pâleur","cyanose"],"explanation":"Pâleur à la surélévation du pied et cyanose de déclivité, avec un allongement du temps de recoloration pulpaire, orientent vers une artériopathie.","src":"p. 328"},{"id":"d228-qroc-009","type":"QROC","rank":"A","objective":"d228-obj-04","tags":["clinique","physiopathologie"],"difficulty":2,"question":"Quel pigment explique la couleur brune de la dermite ocre de l'insuffisance veineuse ?","answer":"L'hémosidérine","accept":["hémosidérine"],"keywords":["hémosidérin"],"explanation":"La dermite ocre forme de larges macules malléolaires internes ou de la face antérieure des tibias, rouge violacé au début puis brunes à cause des dépôts d'hémosidérine.","src":"p. 328"},{"id":"d228-qroc-010","type":"QROC","rank":"A","objective":"d228-obj-04","tags":["clinique"],"difficulty":2,"question":"Quelle lésion de capillarite, faite de plaques ivoire atrophiques parfois parcourues de télangiectasies, tend à s'ulcérer (+++) ?","answer":"L'atrophie blanche","accept":["atrophie blanche"],"keywords":["atrophie"],"explanation":"L'atrophie blanche est souvent douloureuse et tend à l'ulcération ; elle fait partie des lésions de capillarite avec la dermite ocre et les capillarités hypertrophiques.","src":"p. 328"},{"id":"d228-qroc-011","type":"QROC","rank":"A","objective":"d228-obj-04","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on l'hypodermite scléreuse, qui fait suite à des épisodes répétés d'hypodermite aiguë de l'insuffisance veineuse ?","answer":"La lipodermatosclérose","accept":["lipodermatosclérose"],"keywords":["lipoderma"],"explanation":"Le mollet est dur, à peau scléreuse, souvent pigmentée, réalisant une guêtre rétractile ; l'hypodermite aiguë ou subaiguë correspondante est une grosse jambe rouge, douloureuse, d'apparition progressive et non fébrile.","src":"p. 328"},{"id":"d228-qroc-012","type":"QROC","rank":"A","objective":"d228-obj-02","tags":["clinique","pronostic"],"difficulty":2,"question":"Quel aspect des bords d'un ulcère retarde la cicatrisation ?","answer":"Des bords durs, faisant saillie au-dessus de l'ulcère","accept":["bords durs","durs"],"keywords":["dur"],"explanation":"Des bords souples, au même niveau que l'ulcère, sont de bon pronostic ; des bords durs et saillants retardent la cicatrisation.","src":"p. 327"},{"id":"d228-qroc-013","type":"QROC","rank":"A","objective":"d228-obj-11","tags":["imagerie","paraclinique"],"difficulty":1,"question":"Quel examen d'imagerie est demandé en première intention devant un ulcère de jambe ?","answer":"L'échographie Doppler artérioveineuse","accept":["échographie Doppler","écho-Doppler","Doppler"],"keywords":["doppler"],"explanation":"Un ulcère justifie un examen vasculaire clinique complet et une échographie Doppler veineuse et/ou artérielle avec mesure de l'IPS (index de pression systolique).","src":"p. 325, 329"},{"id":"d228-qroc-014","type":"QROC","rank":"A","objective":"d228-obj-02","tags":["paraclinique","diagnostic"],"difficulty":2,"question":"Pour quelles valeurs d'IPS faut-il compléter l'échographie Doppler veineuse par une échographie Doppler artérielle ?","answer":"IPS < 0,9 ou > 1,3","accept":["< 0,9 ou > 1,3","inférieur à 0,9 ou supérieur à 1,3","moins de 0,9 ou plus de 1,3"],"keywords":["0,9","1,3"],"explanation":"L'échographie Doppler artérielle est aussi nécessaire en cas d'abolition des pouls périphériques ou de signes cliniques d'AOMI.","src":"p. 331"},{"id":"d228-qroc-015","type":"QROC","rank":"A","objective":"d228-obj-02","tags":["diagnostic"],"difficulty":2,"question":"Que conclut-on devant un ulcère veineux dont l'IPS est compris entre 0,7 et 0,9 ?","answer":"Un ulcère mixte à prédominance veineuse","accept":["ulcère mixte","mixte à prédominance veineuse","mixte"],"keywords":["mixte"],"explanation":"Avec un IPS entre 0,7 et 0,9, l'AOMI n'explique pas à elle seule l'ulcère : il est mixte, à prédominance veineuse.","src":"p. 331"},{"id":"d228-qroc-016","type":"QROC","rank":"A","objective":"d228-obj-02","tags":["diagnostic","pièges"],"difficulty":2,"question":"Que traduit un IPS supérieur à 1,3, notamment chez le diabétique ?","answer":"Des artères incompressibles (calcifiées)","accept":["artères incompressibles","incompressibles","calcifiées"],"keywords":["incompressible"],"explanation":"Un IPS supérieur à 1,3 traduit des artères calcifiées incompressibles, souvent en cas de diabète : l'échographie Doppler artérielle doit alors compléter l'exploration.","src":"p. 329, 331"},{"id":"d228-qroc-017","type":"QROC","rank":"A","objective":"d228-obj-05","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quels sont les deux signes qui orientent vers une cause artérielle ou artériolaire (angiodermite nécrotique comprise) devant un ulcère ?","answer":"Douleur (surtout de décubitus) et extension nécrotique","accept":["douleur de décubitus et extension nécrotique"],"keywords":["douleur","nécro"],"explanation":"La douleur, en particulier de décubitus, et l'extension nécrotique orientent vers une cause artérielle ou artériolaire ; les modifications de la peau péri-ulcéreuse sont plus fréquentes dans les ulcères veineux.","src":"p. 338"},{"id":"d228-qroc-018","type":"QROC","rank":"A","objective":"d228-obj-02","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quels sont les deux symptômes d'artériopathie à rechercher à l'interrogatoire d'un patient porteur d'un ulcère de jambe ?","answer":"Claudication intermittente et douleurs de décubitus","accept":["claudication intermittente et douleurs de décubitus"],"keywords":["claudication","décubitus"],"explanation":"L'interrogatoire recherche aussi des signes d'insuffisance veineuse (lourdeur de jambes, phlébalgies, œdème vespéral, crampes au repos), les antécédents de varices ou de thrombose et les facteurs de risque vasculaire.","src":"p. 330"},{"id":"d228-qroc-019","type":"QROC","rank":"A","objective":"d228-obj-13","tags":["définition","traitement"],"difficulty":1,"question":"Quelles sont les trois phases successives de la cicatrisation d'un ulcère de jambe ?","answer":"Détersion, bourgeonnement, épidermisation","accept":["détersion, bourgeonnement, épithélialisation","détersion bourgeonnement épidermisation"],"keywords":["détersion","bourgeon"],"explanation":"Les soins locaux sont adaptés à chacune des trois phases : détersion, bourgeonnement, puis épidermisation (ré-épithélialisation).","src":"p. 326, 337-338"},{"id":"d228-qroc-020","type":"QROC","rank":"A","objective":"d228-obj-15","tags":["complications","pièges"],"difficulty":1,"question":"Comment nomme-t-on la présence de germes sur un ulcère, sans signe d'infection ?","answer":"Une colonisation","accept":["colonisation"],"keywords":["colonis"],"explanation":"C'est un phénomène non pathologique : elle ne justifie ni prélèvement bactériologique, ni traitement antiseptique ou antibiotique systématique.","src":"p. 334"},{"id":"d228-qroc-021","type":"QROC","rank":"B","objective":"d228-obj-03","tags":["physiopathologie"],"difficulty":2,"question":"Quel mécanisme est à l'origine d'un ulcère de jambe veineux pur ?","answer":"Une hypertension veineuse","accept":["hypertension veineuse"],"keywords":["hypertension"],"explanation":"L'hypertension veineuse, secondaire à un reflux superficiel, à un reflux et/ou une obstruction profonds (post-thrombotique) ou à une déficience de la pompe musculaire du mollet, entraîne une souffrance microcirculatoire et tissulaire.","src":"p. 326"},{"id":"d228-qroc-022","type":"QROC","rank":"A","objective":"d228-obj-15","tags":["prévention","complications"],"difficulty":1,"question":"Quelle prévention systématique est rappelée (+++) chez un patient non immunisé porteur d'un ulcère de jambe ?","answer":"La vaccination antitétanique","accept":["antitétanique","tétanos"],"keywords":["tétan"],"explanation":"Le tétanos doit être prévenu systématiquement par vaccination chez les malades non immunisés ; la mise à jour de la vaccination antitétanique fait partie du traitement général.","src":"p. 334, 336"},{"id":"d228-qroc-023","type":"QROC","rank":"A","objective":"d228-obj-15","tags":["complications","paraclinique"],"difficulty":1,"question":"Quel examen permet d'identifier l'allergène en cas de dermatite de contact sur un ulcère ?","answer":"Les tests épicutanés","accept":["épicutanés","tests épicutanés"],"keywords":["épicutan"],"explanation":"La dermatite de contact est fréquente en raison du grand nombre de topiques utilisés sur une barrière cutanée altérée ; elle peut diffuser à distance de la zone d'application.","src":"p. 334"},{"id":"d228-qroc-024","type":"QROC","rank":"A","objective":"d228-obj-15","tags":["complications","pièges"],"difficulty":2,"question":"Quel allergène classique faut-il éviter dans le choix d'un tulle vaseliné pour un ulcère ?","answer":"Le baume du Pérou","accept":["baume du Pérou"],"keywords":["baume"],"explanation":"Le baume du Pérou est l'un des principaux allergènes, avec certains antiseptiques, les fragrances, la lanoline, les conservateurs et certains pansements.","src":"p. 334, 337"},{"id":"d228-qroc-025","type":"QROC","rank":"A","objective":"d228-obj-15","tags":["complications","diagnostic"],"difficulty":2,"question":"Quelle transformation maligne rare et tardive faut-il redouter sur un ulcère de jambe chronique ?","answer":"Un carcinome épidermoïde","accept":["carcinome épidermoïde","épidermoïde"],"keywords":["épidermoïde"],"explanation":"Il est à évoquer devant la chronicité de l'ulcère, des douleurs, une hémorragie locale ou un bourgeonnement excessif ; la biopsie, parfois répétée, fait le diagnostic.","src":"p. 335"},{"id":"d228-qroc-026","type":"QROC","rank":"A","objective":"d228-obj-15","tags":["complications","traitement"],"difficulty":2,"question":"Quelle est la prise en charge d'une hémorragie par saignement d'une varice sur un ulcère veineux ?","answer":"Compression et surélévation du membre","accept":["compression et surélévation"],"keywords":["compression","surélévation"],"explanation":"L'hémorragie survient souvent dans le cadre d'ulcères veineux, par saignement d'une varice ; elle est traitée par compression et surélévation du membre.","src":"p. 335"},{"id":"d228-qroc-027","type":"QROC","rank":"A","objective":"d228-obj-10","tags":["traitement"],"difficulty":1,"question":"Quel traitement systématique de l'ulcère veineux lutte contre l'œdème et diminue le reflux par effet mécanique ?","answer":"La compression","accept":["compression","contention"],"keywords":["compress"],"explanation":"La compression est systématique dans l'ulcère veineux ; elle est complétée si besoin par la chirurgie veineuse et les greffes.","src":"p. 335"},{"id":"d228-qroc-028","type":"QROC","rank":"A","objective":"d228-obj-10","tags":["traitement"],"difficulty":2,"question":"Quelle pression de compression à la cheville est recommandée dans l'ulcère veineux lorsque l'IPS est compris entre 0,8 et 1,3 ?","answer":"30 à 40 mmHg","accept":["30-40 mmHg","30 à 40"],"keywords":["30","40"],"explanation":"C'est une compression à haut niveau de pression, de préférence multicouche, bien observée et portée toute la journée.","src":"p. 335"},{"id":"d228-qroc-029","type":"QROC","rank":"A","objective":"d228-obj-10","tags":["traitement"],"difficulty":2,"question":"Sous quelle pression faut-il adapter la compression d'un ulcère mixte à prédominance veineuse (IPS > 0,7) ?","answer":"Sous 30 mmHg, avec des bandes à étirement court","accept":["sous 30 mmHg","moins de 30 mmHg","< 30 mmHg"],"keywords":["30 mmhg"],"explanation":"Dans l'ulcère mixte à prédominance veineuse, on prend en charge l'AOMI et on diminue la pression sous 30 mmHg (si l'IPS est > 0,7), avec des bandes à étirement court, sous surveillance médicale.","src":"p. 336"},{"id":"d228-qroc-030","type":"QROC","rank":"A","objective":"d228-obj-10","tags":["traitement"],"difficulty":2,"question":"Quel geste chirurgical traite l'insuffisance veineuse superficielle d'un ulcère en l'absence d'obstruction et de reflux veineux profond axial ?","answer":"L'éveinage","accept":["éveinage"],"keywords":["éveinage"],"explanation":"Il est nécessaire d'opérer par éveinage les insuffisances veineuses superficielles sans obstruction ni reflux veineux profond axial ; la sclérothérapie sert surtout de complément à la chirurgie.","src":"p. 335"},{"id":"d228-qroc-031","type":"QROC","rank":"A","objective":"d228-obj-14","tags":["traitement"],"difficulty":2,"question":"À partir de quelle taille d'ulcère, ou de quelle durée sans cicatrisation, envisage-t-on des greffes cutanées ?","answer":"> 10 cm² ou plus de 6 mois","accept":["10 cm2 ou 6 mois","plus de 10 cm2 ou plus de 6 mois"],"keywords":["10","6 mois"],"explanation":"Les greffes en pastilles ou en résille ont un effet antalgique et raccourcissent la durée de cicatrisation ; elles sont indiquées pour les ulcères de grande taille (> 10 cm²) et les ulcères rebelles depuis plus de 6 mois.","src":"p. 335, 337"},{"id":"d228-qroc-032","type":"QROC","rank":"A","objective":"d228-obj-14","tags":["traitement"],"difficulty":2,"question":"Quels topiques favorisent la détersion de la fibrine ou de la nécrose et restent en place 48 à 72 heures ?","answer":"Alginates et hydrogels","accept":["alginates et hydrogels","hydrogels et alginates"],"keywords":["alginate","hydrogel"],"explanation":"Ces topiques sont laissés 48 à 72 heures selon le suintement, en l'absence d'infection patente ; les débris sont enlevés au bistouri, à la curette ou aux ciseaux, après antalgique si besoin.","src":"p. 337"},{"id":"d228-qroc-033","type":"QROC","rank":"A","objective":"d228-obj-14","tags":["traitement","pièges"],"difficulty":1,"question":"Quels produits faut-il éviter pour nettoyer un ulcère en l'absence d'infection déclarée (++) ?","answer":"Les antiseptiques","accept":["antiseptique"],"keywords":["antiseptique"],"explanation":"Le nettoyage se fait à la douchette, l'eau stérile étant inutile, sans antiseptique tant qu'il n'y a pas d'infection déclarée.","src":"p. 337"},{"id":"d228-qroc-034","type":"QROC","rank":"A","objective":"d228-obj-14","tags":["traitement"],"difficulty":2,"question":"Quels pansements choisit-on en phase de bourgeonnement pour une plaie très exsudative ?","answer":"Alginates de calcium et hydrofibres","accept":["alginates de calcium et hydrofibres","hydrofibres et alginates"],"keywords":["alginate","hydrofibre"],"explanation":"Les alginates de calcium sont aussi hémostatiques ; pour les autres plaies, on utilise des tulles vaselinés ou des hydrocolloïdes, hydrocellulaires et interfaces.","src":"p. 337"},{"id":"d228-qroc-035","type":"QROC","rank":"A","objective":"d228-obj-14","tags":["traitement"],"difficulty":1,"question":"Quel pansement utilise-t-on sur un ulcère inflammatoire fortement colonisé (érythème périlésionnel, plaie malodorante, exsudat abondant) ?","answer":"Un pansement à l'argent","accept":["argent"],"keywords":["argent"],"explanation":"Les pansements à l'argent sont réservés aux ulcères à caractère inflammatoire qui évoquent une forte colonisation bactérienne.","src":"p. 338"},{"id":"d228-qroc-036","type":"QROC","rank":"A","objective":"d228-obj-14","tags":["traitement","complications"],"difficulty":1,"question":"Quel est le traitement local d'un eczéma de contact de la peau péri-ulcéreuse ?","answer":"Suppression de l'allergène et dermocorticoïdes","accept":["éviction de l'allergène et dermocorticoïdes"],"keywords":["allergène","dermocorticoïde"],"explanation":"Pour la peau péri-ulcéreuse : compression veineuse systématique, suppression de l'allergène et dermocorticoïdes en cas d'eczéma de contact, désinfection et antibiothérapie générale en cas de dermohypodermite bactérienne.","src":"p. 338"},{"id":"d228-qroc-037","type":"QROC","rank":"A","objective":"d228-obj-15","tags":["pronostic","suivi"],"difficulty":2,"question":"En combien de temps un ulcère variqueux cicatrise-t-il sous traitement étiologique et local bien conduit ?","answer":"3 à 6 mois","accept":["3-6 mois","3 à 6 mois"],"keywords":["3","6"],"explanation":"La cicatrisation prend 3 à 6 mois, mais les récidives et le passage à la chronicité ne sont pas rares.","src":"p. 333"},{"id":"d228-qroc-038","type":"QROC","rank":"A","objective":"d228-obj-15","tags":["pronostic"],"difficulty":1,"question":"Quel type d'ulcère est le plus rebelle et le plus chronique ?","answer":"L'ulcère post-thrombotique","accept":["post-thrombotique"],"keywords":["thrombotique"],"explanation":"Il est plus rebelle en raison de troubles péri-ulcéreux souvent importants, de perturbations hémodynamiques et de la difficulté du traitement étiologique.","src":"p. 333, 338"},{"id":"d228-qroc-039","type":"QROC","rank":"B","objective":"d228-obj-06","tags":["clinique"],"difficulty":2,"question":"Quel aspect des ulcérations superficielles à bords irréguliers est évocateur d'une angiodermite nécrotique ?","answer":"En « carte de géographie »","accept":["carte de géographie"],"keywords":["carte"],"explanation":"L'angiodermite nécrotique débute brutalement par une plaque purpurique ou livedoïde extensive, évolue vers une nécrose noirâtre puis des ulcérations superficielles en carte de géographie, très douloureuses, à la face antéro-externe de la jambe.","src":"p. 331"},{"id":"d228-qroc-040","type":"QROC","rank":"B","objective":"d228-obj-07","tags":["physiopathologie"],"difficulty":2,"question":"Quel mécanisme est à l'origine de l'infarctus cutané de l'angiodermite nécrotique ?","answer":"Une occlusion artériolaire (artériolosclérose)","accept":["artériolosclérose","occlusion artériolaire"],"keywords":["artériol"],"explanation":"L'angiodermite nécrotique est un infarctus cutané secondaire à une occlusion artériolaire (artériolosclérose des vaisseaux du derme), sur un terrain de femme après 60 ans, d'HTA et de diabète.","src":"p. 331"},{"id":"d228-qroc-041","type":"QROC","rank":"B","objective":"d228-obj-09","tags":["étiologie","diagnostic"],"difficulty":2,"question":"Quelle cause inflammatoire d'ulcère débute par une pustule, puis une ulcération douloureuse à extension rapide entourée d'un bourrelet violacé ?","answer":"Le pyoderma gangrenosum","accept":["pyoderma gangrenosum","pyoderma"],"keywords":["pyoderma"],"explanation":"Le pyoderma gangrenosum forme des clapiers purulents entourés d'un bourrelet périphérique violacé caractéristique ; il peut s'associer à une hémopathie ou à une maladie inflammatoire du tube digestif.","src":"p. 332"},{"id":"d228-qroc-042","type":"QROC","rank":"B","objective":"d228-obj-09","tags":["étiologie","pièges"],"difficulty":2,"question":"Après combien de temps de traitement bien conduit sans évolution favorable doit-on rechercher une cause non vasculaire d'ulcère ?","answer":"2 à 3 mois","accept":["2-3 mois","2 à 3 mois"],"keywords":["2","3"],"explanation":"On y pense aussi devant des examens artériel et veineux normaux, une évolution ulcérante rapide, une anomalie du fond, du bord ou de la périphérie, ou un siège atypique.","src":"p. 332"},{"id":"d228-qroc-043","type":"QROC","rank":"B","objective":"d228-obj-09","tags":["diagnostic"],"difficulty":1,"question":"Comment nomme-t-on l'ulcération neurologique indolore de la plante du pied, localisée sur les points d'appui (talon, têtes métatarsiennes) ?","answer":"Le mal perforant plantaire","accept":["mal perforant"],"keywords":["perforant"],"explanation":"Le mal perforant plantaire débute par une hyperkératose qui s'ulcère, sur le talon ou la tête des métatarsiens ; il est indolore, ce qui explique son aggravation, et le diabète en est la principale cause.","src":"p. 333"},{"id":"d228-qroc-044","type":"QROC","rank":"B","objective":"d228-obj-12","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Quelle est la valeur normale de l'IPS (pression tibiale / pression humérale) ?","answer":"1 à 1,3","accept":["1-1,3","1 à 1,3"],"keywords":["1,3"],"explanation":"L'IPS est le rapport entre la pression tibiale antérieure ou postérieure et la pression humérale ; sa valeur normale est de 1 à 1,3.","src":"p. 329"},{"id":"d228-qroc-045","type":"QROC","rank":"A","objective":"d228-obj-12","tags":["diagnostic","urgence"],"difficulty":2,"question":"Quels seuils de pression artérielle systolique définissent l'ischémie critique d'un ulcère artériel (cheville, gros orteil) ?","answer":"< 50 mmHg à la cheville ou < 30 mmHg au gros orteil","accept":["50 mmHg à la cheville et 30 mmHg au gros orteil","50 mmHg cheville, 30 mmHg gros orteil"],"keywords":["50","30"],"explanation":"En cas d'ischémie critique, l'hospitalisation en milieu spécialisé est recommandée.","src":"p. 329"},{"id":"d228-qcm-101","type":"QRM","rank":"A","objective":"d228-obj-05","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un homme de 67 ans, tabagique et diabétique, consulte pour un ulcère creusant de l'avant-pied, très douloureux, avec une peau péri-ulcéreuse lisse, froide et dépilée. Quels éléments confortent le diagnostic d'ulcère artériel ?","options":[{"t":"Un terrain d'homme de plus de 50 ans avec facteurs de risque vasculaire","ok":true,"why":"L'ulcère artériel touche surtout l'homme de plus de 50 ans, avec tabac, HTA, diabète, obésité, dyslipidémie."},{"t":"Une abolition d'un ou plusieurs pouls périphériques","ok":true,"why":"C'est un signe de l'examen vasculaire de l'ulcère artériel."},{"t":"Un allongement du temps de recoloration pulpaire","ok":true,"why":"Avec la baisse de température cutanée et la pâleur à la surélévation, il évoque l'artériopathie."},{"t":"Des varices avec un examen artériel normal","ok":false,"why":"C'est l'examen de l'ulcère veineux."},{"t":"Un œdème plus marqué en cas de syndrome post-phlébitique","ok":false,"why":"L'œdème, surtout post-phlébitique, est un signe de l'ulcère veineux."}],"explanation":"Ulcère artériel : homme de plus de 50 ans avec facteurs de risque, ulcère creusant distal, douleur intense, peau lisse froide dépilée, pouls abolis.","src":"p. 328-329"},{"id":"d228-qcm-102","type":"QRM","rank":"A","objective":"d228-obj-04","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Une femme de 72 ans, en surpoids, présente un ulcère unique de 6 cm, moyennement douloureux, situé au-dessus de la malléole interne. Quels éléments sont en faveur d'un ulcère veineux ?","options":[{"t":"Une dermite ocre autour de l'ulcère","ok":true,"why":"C'est une lésion de capillarite caractéristique de l'insuffisance veineuse."},{"t":"La présence de varices avec un examen artériel normal","ok":true,"why":"C'est le tableau de l'ulcère veineux."},{"t":"Un œdème, plus marqué en cas de syndrome post-phlébitique","ok":true,"why":"L'œdème fait partie du tableau veineux."},{"t":"Des pouls périphériques abolis","ok":false,"why":"L'abolition d'un ou plusieurs pouls périphériques oriente vers un ulcère artériel."},{"t":"Une peau péri-ulcéreuse lisse, froide et dépilée","ok":false,"why":"Cet aspect est celui de l'ulcère artériel."}],"explanation":"Ulcère veineux : femme de plus de 50 ans, ulcère unique de grande taille, périmalléolaire, moyennement douloureux, avec varices, œdème et lésions de la peau péri-ulcéreuse.","src":"p. 327-329"},{"id":"d228-qcm-103","type":"QRM","rank":"A","objective":"d228-obj-02","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Concernant l'IPS devant un ulcère de jambe, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Un IPS entre 0,7 et 0,9 oriente vers un ulcère mixte à prédominance veineuse","ok":true,"why":"Dans ce cas, l'AOMI n'explique pas à elle seule l'ulcère."},{"t":"Un IPS supérieur à 1,3 permet d'exclure une artériopathie","ok":false,"why":"Il traduit des artères calcifiées incompressibles, souvent en cas de diabète, et justifie une échographie Doppler artérielle."},{"t":"Un IPS inférieur à 0,9 dispense de l'échographie Doppler artérielle","ok":false,"why":"Un IPS inférieur à 0,9 impose au contraire de compléter par une échographie Doppler artérielle."},{"t":"L'IPS est inutile devant un ulcère veineux","ok":false,"why":"L'échographie Doppler veineuse est systématiquement associée à la mesure de l'IPS."},{"t":"Un IPS entre 0,7 et 0,9 autorise une compression à haut niveau de pression sans adaptation","ok":false,"why":"Dans l'ulcère mixte, la pression est diminuée sous 30 mmHg avec des bandes à étirement court."}],"explanation":"L'IPS entre 0,7 et 0,9 définit l'ulcère mixte à prédominance veineuse ; hors de 0,9-1,3, l'échographie Doppler artérielle est nécessaire.","src":"p. 329, 331, 336"},{"id":"d228-qcm-104","type":"QRM","rank":"A","objective":"d228-obj-02","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Devant un ulcère veineux, dans quelles situations l'échographie Doppler veineuse avec IPS doit-elle être complétée par une échographie Doppler artérielle ?","options":[{"t":"Une abolition des pouls périphériques","ok":true,"why":"Elle fait suspecter une AOMI associée."},{"t":"Des symptômes ou signes cliniques d'AOMI","ok":true,"why":"Ils justifient l'exploration artérielle."},{"t":"Un IPS inférieur à 0,9 ou supérieur à 1,3","ok":true,"why":"Un IPS supérieur à 1,3 traduit des artères incompressibles, souvent chez le diabétique."},{"t":"La seule présence de varices","ok":false,"why":"Les varices font partie du tableau veineux et ne justifient pas à elles seules l'échographie artérielle."},{"t":"Une taille d'ulcère supérieure à 10 cm²","ok":false,"why":"Cette taille est un critère de recours aux greffes, pas à l'exploration artérielle."}],"explanation":"Trois situations : abolition des pouls, signes cliniques d'AOMI, IPS < 0,9 ou > 1,3.","src":"p. 331, 335"},{"id":"d228-qcm-105","type":"QRM","rank":"A","objective":"d228-obj-15","tags":["complications","pièges"],"difficulty":2,"stem":"À propos de la présence de germes sur un ulcère de jambe sans signe d'infection, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Il s'agit d'une colonisation non pathologique","ok":true,"why":"Elle ne justifie ni prélèvement, ni antiseptique, ni antibiotique systématiques."},{"t":"Un prélèvement bactériologique systématique est justifié","ok":false,"why":"Ce n'est pas justifié en cas de simple colonisation."},{"t":"Un traitement antiseptique systématique est recommandé","ok":false,"why":"Les antiseptiques ne sont pas systématiques ; ils sont évités en l'absence d'infection déclarée."},{"t":"Une antibiothérapie systématique est recommandée","ok":false,"why":"L'antibiothérapie n'est pas systématique en cas de colonisation."},{"t":"Elle traduit toujours une dermohypodermite bactérienne","ok":false,"why":"L'infection patente se reconnaît à la douleur, à l'inflammation des bords, à la lymphangite ou à la fièvre."}],"explanation":"La présence de germes sur un ulcère est une colonisation : ni prélèvement, ni antiseptique, ni antibiotique systématiques.","src":"p. 334"},{"id":"d228-qcm-106","type":"QRM","rank":"A","objective":"d228-obj-15","tags":["complications","clinique"],"difficulty":2,"stem":"Quels éléments font évoquer une infection cutanée patente à partir d'un ulcère de jambe ?","options":[{"t":"Une augmentation de la douleur locale","ok":true,"why":"C'est l'un des signes d'alerte."},{"t":"Une inflammation des bords de l'ulcère","ok":true,"why":"C'est un signe non spécifique, mais à prendre en compte."},{"t":"Une lymphangite","ok":true,"why":"Elle traduit une infection cutanée patente."},{"t":"Une fièvre","ok":true,"why":"Elle évoque une dermohypodermite bactérienne."},{"t":"La seule présence de germes à la culture du fond de l'ulcère","ok":false,"why":"C'est une colonisation non pathologique."}],"explanation":"Douleur locale accrue, inflammation des bords, lymphangite et fièvre font évoquer une dermohypodermite bactérienne ; la colonisation seule ne suffit pas.","src":"p. 334"},{"id":"d228-qcm-107","type":"QRM","rank":"A","objective":"d228-obj-15","tags":["complications","diagnostic"],"difficulty":2,"stem":"À propos du carcinome épidermoïde sur un ulcère de jambe, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Il est rare et tardif, évoqué devant un bourgeonnement excessif","ok":true,"why":"On y pense aussi devant la chronicité, des douleurs ou une hémorragie locale."},{"t":"Il est fréquent et survient dès les premières semaines d'évolution","ok":false,"why":"Il est rare et tardif."},{"t":"Une seule biopsie négative suffit à l'exclure définitivement","ok":false,"why":"La biopsie doit parfois être répétée pour faire le diagnostic."},{"t":"Il se manifeste plutôt par la disparition des douleurs locales","ok":false,"why":"L'apparition de douleurs est un signe d'alerte."},{"t":"Il est évoqué devant une cicatrisation rapide de l'ulcère","ok":false,"why":"C'est la chronicité de l'ulcère qui y fait penser."}],"explanation":"Carcinome épidermoïde : rare et tardif ; chronicité, douleurs, hémorragie locale, bourgeonnement excessif ; biopsie parfois répétée.","src":"p. 335"},{"id":"d228-qcm-108","type":"QRM","rank":"A","objective":"d228-obj-10","tags":["traitement"],"difficulty":2,"stem":"Concernant la compression dans l'ulcère veineux, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Elle est systématique : elle lutte contre l'œdème et diminue le reflux","ok":true,"why":"Elle agit par effet mécanique."},{"t":"Un haut niveau de pression (30 à 40 mmHg) est recommandé si l'IPS est entre 0,8 et 1,3","ok":true,"why":"C'est le niveau recommandé en l'absence d'AOMI."},{"t":"Les compressions multicouches sont à favoriser, à porter toute la journée","ok":true,"why":"Il faut aussi obtenir une bonne observance."},{"t":"Elle est contre-indiquée en présence d'un œdème de la jambe","ok":false,"why":"Elle sert au contraire à lutter contre l'œdème."},{"t":"Elle n'est portée que la nuit pour améliorer l'observance du patient","ok":false,"why":"La compression doit être portée toute la journée."}],"explanation":"Compression systématique, à haut niveau de pression (30 à 40 mmHg), multicouche et portée toute la journée si IPS entre 0,8 et 1,3.","src":"p. 335"},{"id":"d228-qcm-109","type":"QRM","rank":"A","objective":"d228-obj-10","tags":["traitement"],"difficulty":3,"stem":"Un patient de 70 ans a un ulcère veineux avec un IPS à 0,75 : l'ulcère est mixte à prédominance veineuse. Quelle(s) mesure(s) est (sont) adaptée(s) ?","options":[{"t":"Prendre en charge l'AOMI","ok":true,"why":"C'est la première mesure de l'ulcère mixte à prédominance veineuse."},{"t":"Adapter la compression sous 30 mmHg, avec des bandes à étirement court, sous surveillance médicale","ok":true,"why":"C'est possible si l'IPS est supérieur à 0,7."},{"t":"Appliquer d'emblée une compression à haut niveau de pression de 30 à 40 mmHg","ok":false,"why":"Cette compression est réservée à l'ulcère veineux sans AOMI."},{"t":"Supprimer définitivement toute compression","ok":false,"why":"La compression est adaptée, pas supprimée."},{"t":"Proposer uniquement une greffe en pastilles","ok":false,"why":"Les greffes sont réservées aux ulcères de grande taille ou rebelles depuis plus de 6 mois."}],"explanation":"Ulcère mixte à prédominance veineuse : prise en charge de l'AOMI et compression diminuée sous 30 mmHg avec bandes à étirement court sous surveillance.","trap":"Ne pas appliquer la compression forte de l'ulcère veineux pur à un ulcère mixte.","src":"p. 335-336"},{"id":"d228-qcm-110","type":"QRM","rank":"A","objective":"d228-obj-10","tags":["traitement"],"difficulty":2,"stem":"À propos du traitement chirurgical des ulcères de jambe, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"L'éveinage traite l'insuffisance veineuse superficielle sans reflux profond axial ni obstruction","ok":true,"why":"C'est l'indication de la chirurgie veineuse."},{"t":"La chirurgie est à envisager en priorité dans les ulcères de cause artérielle","ok":true,"why":"Elle l'est aussi dans les ulcères par insuffisance veineuse non post-thrombotique."},{"t":"La sclérothérapie a démontré sa supériorité sur la chirurgie dans des études comparatives","ok":false,"why":"Elle n'a pas fait l'objet d'études comparatives d'efficacité et sert surtout de complément à la chirurgie."},{"t":"La chirurgie est la première option dans l'ulcère post-thrombotique","ok":false,"why":"La priorité concerne l'insuffisance veineuse non post-thrombotique."},{"t":"Les greffes cutanées sont indiquées dès le premier mois d'évolution","ok":false,"why":"Elles sont indiquées pour les ulcères de plus de 10 cm² ou rebelles depuis plus de 6 mois."}],"explanation":"Éveinage de l'insuffisance veineuse superficielle sans obstruction ni reflux profond ; chirurgie en priorité pour les ulcères artériels et par insuffisance veineuse non post-thrombotique ; greffes si > 10 cm² ou > 6 mois.","src":"p. 335, 338"},{"id":"d228-qcm-111","type":"QRM","rank":"A","objective":"d228-obj-14","tags":["traitement"],"difficulty":2,"stem":"À propos des soins locaux d'un ulcère de jambe en phase de détersion, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Le nettoyage se fait à la douchette, l'eau stérile étant inutile","ok":true,"why":"L'eau stérile n'est pas nécessaire."},{"t":"Les alginates et hydrogels favorisent la détersion de la fibrine ou de la nécrose","ok":true,"why":"Ils sont laissés en place 48 à 72 heures selon le suintement."},{"t":"Les antiseptiques ne sont pas utilisés en l'absence d'infection déclarée","ok":true,"why":"Il n'y a pas d'antiseptique sans infection déclarée (++)."},{"t":"L'eau stérile est indispensable pour le nettoyage","ok":false,"why":"Elle est inutile."},{"t":"Un antiseptique est appliqué systématiquement à chaque pansement","ok":false,"why":"L'antiseptique n'est pas systématique."}],"explanation":"Détersion : nettoyage à la douchette sans antiseptique tant qu'il n'y a pas d'infection déclarée, ablation des débris, alginates et hydrogels 48 à 72 heures.","src":"p. 337"},{"id":"d228-qcm-112","type":"QRM","rank":"A","objective":"d228-obj-14","tags":["traitement"],"difficulty":2,"stem":"Dans quelle(s) situation(s) un pansement à l'argent est-il indiqué ?","options":[{"t":"Ulcère inflammatoire très colonisé : érythème, odeur, exsudat abondant","ok":true,"why":"Ce sont les trois caractères qui évoquent une forte colonisation bactérienne."},{"t":"Détersion de tout ulcère propre, non inflammatoire et peu exsudatif","ok":false,"why":"La détersion fait appel à des alginates et hydrogels."},{"t":"Prévention systématique de la dermatite de contact de la peau péri-ulcéreuse","ok":false,"why":"Le traitement de l'eczéma de contact repose sur la suppression de l'allergène et les dermocorticoïdes."},{"t":"Ulcère artériel douloureux, sans aucun signe inflammatoire local","ok":false,"why":"L'indication repose sur le caractère inflammatoire et la forte colonisation."},{"t":"Plaie bourgeonnante peu exsudative et non inflammatoire, sans odeur","ok":false,"why":"On utilise alors tulles vaselinés, hydrocolloïdes, hydrocellulaires ou interfaces."}],"explanation":"Les pansements à l'argent sont réservés aux ulcères à caractère inflammatoire (érythème périlésionnel, plaie malodorante, exsudat abondant) évoquant une forte colonisation.","src":"p. 337-338"},{"id":"d228-qcm-113","type":"QRM","rank":"A","objective":"d228-obj-14","tags":["traitement","prévention"],"difficulty":2,"stem":"Concernant le traitement général d'un patient porteur d'un ulcère de jambe, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La vaccination antitétanique doit être mise à jour","ok":true,"why":"C'est une mesure générale systématique."},{"t":"Le repos strict au lit est recommandé jusqu'à la cicatrisation","ok":false,"why":"Une activité physique adaptée, avec kinésithérapie si besoin, est recommandée."},{"t":"Il n'est pas nécessaire de traiter la douleur avant les soins","ok":false,"why":"Les antalgiques sont prescrits si besoin, en particulier avant les soins."},{"t":"Les facteurs de risque vasculaire n'ont pas à être corrigés","ok":false,"why":"L'arrêt du tabac, l'équilibre du diabète, le traitement de l'HTA et de l'hyperlipidémie et la perte de poids sont recommandés."},{"t":"L'évaluation nutritionnelle est inutile en cas de retard de cicatrisation","ok":false,"why":"L'évaluation du statut nutritionnel est recommandée en cas de retard de cicatrisation."}],"explanation":"Traitement général : vaccination antitétanique, traitement de la douleur, correction des facteurs de risque vasculaire, activité physique adaptée, prise en compte du contexte social et de la nutrition.","src":"p. 336"},{"id":"d228-qcm-114","type":"QRM","rank":"A","objective":"d228-obj-15","tags":["pronostic","suivi"],"difficulty":2,"stem":"À propos de l'évolution des ulcères de jambe, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"L'ulcère variqueux cicatrise en 3 à 6 mois, avec des récidives non rares","ok":true,"why":"Sous un traitement étiologique et local bien conduit."},{"t":"L'ulcère post-thrombotique cicatrise plus facilement que l'ulcère variqueux","ok":false,"why":"Il est plus rebelle (troubles péri-ulcéreux, perturbations hémodynamiques, traitement étiologique difficile)."},{"t":"L'ulcère artériel ne peut jamais cicatriser","ok":false,"why":"Il peut cicatriser si un traitement étiologique est possible (pontage, dilatation)."},{"t":"L'amputation n'est jamais discutée dans l'ulcère artériel","ok":false,"why":"Elle est parfois nécessaire dans les tableaux évolués sans possibilité de revascularisation."},{"t":"Les récidives sont exceptionnelles après cicatrisation","ok":false,"why":"Les récidives sont fréquentes et doivent être prévenues."}],"explanation":"Ulcère variqueux : cicatrisation en 3 à 6 mois mais récidives ; post-thrombotique plus rebelle ; ulcère artériel dépendant de la possibilité d'un traitement étiologique.","src":"p. 333-334, 338"},{"id":"d228-qcm-115","type":"QRM","rank":"B","objective":"d228-obj-06","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Une femme de 70 ans, hypertendue et diabétique, présente une plaque purpurique livedoïde de la jambe qui évolue vers une nécrose noirâtre. Quels éléments sont évocateurs d'une angiodermite nécrotique ?","options":[{"t":"Des ulcérations superficielles à bords irréguliers, en carte de géographie","ok":true,"why":"C'est l'aspect typique après la nécrose noirâtre."},{"t":"Une localisation suspendue à la face antéro-externe de la jambe","ok":true,"why":"C'est la topographie caractéristique."},{"t":"Des douleurs très importantes, insomniantes","ok":true,"why":"Les douleurs sont intenses."},{"t":"Des grands axes artériels et veineux pathologiques à l'échographie Doppler","ok":false,"why":"Les grands axes artériels et veineux sont normaux."},{"t":"Une cryoglobulinémie positive avec FAN et ANCA positifs","ok":false,"why":"La cryoglobulinémie est négative, de même que les FAN et les ANCA."}],"explanation":"Angiodermite nécrotique : infarctus cutané par occlusion artériolaire, début brutal, nécrose noirâtre, ulcérations en carte de géographie, douleurs intenses, grands axes normaux.","src":"p. 331"},{"id":"d228-qcm-116","type":"QRM","rank":"B","objective":"d228-obj-09","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"Devant un ulcère de jambe, quels éléments doivent faire rechercher une étiologie non vasculaire ?","options":[{"t":"Des examens artériel et veineux normaux n'expliquant pas l'ulcère","ok":true,"why":"L'ulcère reste alors inexpliqué par une cause vasculaire."},{"t":"Une évolution ulcérante rapide","ok":true,"why":"C'est un signe d'alerte."},{"t":"L'absence de cicatrisation après 2 à 3 mois de traitement bien conduit","ok":true,"why":"L'absence d'évolution favorable doit faire discuter une autre cause."},{"t":"Un siège périmalléolaire avec varices et dermite ocre","ok":false,"why":"C'est le tableau habituel de l'ulcère veineux."},{"t":"Une cicatrisation en 3 à 6 mois sous compression","ok":false,"why":"C'est l'évolution habituelle d'un ulcère variqueux bien traité."}],"explanation":"Une autre étiologie est à discuter devant des examens vasculaires normaux, une évolution rapide, l'absence de cicatrisation après 2 à 3 mois, une anomalie du fond ou du bord, ou un siège atypique.","src":"p. 332"},{"id":"d228-qcm-117","type":"QRM","rank":"A","objective":"d228-obj-05","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Quelle(s) lésion(s) de la peau péri-ulcéreuse évoque(nt) une artériopathie plutôt qu'une insuffisance veineuse ?","options":[{"t":"Une peau luisante, dépilée, de température basse","ok":true,"why":"C'est l'aspect de la peau de l'artériopathie."},{"t":"Une dermite ocre par dépôts d'hémosidérine des malléoles","ok":false,"why":"C'est une lésion de capillarite de l'insuffisance veineuse."},{"t":"Une atrophie blanche, plaques ivoire atrophiques","ok":false,"why":"C'est une lésion de capillarite de l'insuffisance veineuse."},{"t":"Un eczéma variqueux prurigineux malléolaire","ok":false,"why":"C'est une lésion dermo-épidermique de l'insuffisance veineuse."},{"t":"Une lipodermatosclérose du mollet scléreux","ok":false,"why":"C'est une hypodermite scléreuse de l'insuffisance veineuse."}],"explanation":"Les modifications de la peau péri-ulcéreuse sont plus fréquentes dans les ulcères veineux (eczéma, dermite ocre, atrophie blanche, lipodermatosclérose) ; l'artériopathie donne une peau luisante, froide et dépilée.","src":"p. 328, 338"},{"id":"d228-qru-101","type":"QRU","rank":"A","objective":"d228-obj-04","tags":["diagnostic","clinique"],"difficulty":1,"stem":"Une femme de 72 ans, en surpoids, présente un ulcère unique de 6 cm, moyennement douloureux, de siège périmalléolaire interne, avec dermite ocre, varices et pouls périphériques perçus. De quel type d'ulcère s'agit-il ?","options":[{"t":"Ulcère veineux","ok":true,"why":"Le terrain, le siège, la dermite ocre et les varices avec un examen artériel normal sont typiques."},{"t":"Ulcère artériel","ok":false,"why":"Il est distal ou suspendu, très douloureux, avec peau froide dépilée et pouls abolis."},{"t":"Angiodermite nécrotique","ok":false,"why":"Elle débute brutalement par une plaque purpurique ou livedoïde et évolue vers une nécrose très douloureuse."},{"t":"Pyoderma gangrenosum","ok":false,"why":"Il débute par une pustule et s'étend rapidement en ulcération douloureuse."},{"t":"Mal perforant plantaire","ok":false,"why":"C'est une ulcération indolore de la plante, sur un point d'appui."}],"explanation":"Femme de plus de 50 ans, ulcère périmalléolaire moyennement douloureux, dermite ocre et varices : ulcère veineux.","src":"p. 327-329"},{"id":"d228-qru-102","type":"QRU","rank":"A","objective":"d228-obj-11","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Un homme de 66 ans, tabagique et diabétique, a un ulcère creusant d'un orteil, avec des douleurs de décubitus, une peau froide et dépilée et des pouls abolis. Quel examen d'imagerie demander en première intention ?","options":[{"t":"Échographie Doppler artérielle avec mesure de l'IPS","ok":true,"why":"L'échographie Doppler est l'imagerie de première intention ; elle confirme l'artériopathie."},{"t":"Angiographie artérielle d'emblée, avant toute autre exploration","ok":false,"why":"Elle est réservée aux cas où une option chirurgicale est envisagée."},{"t":"Échographie Doppler veineuse seule, sans exploration artérielle","ok":false,"why":"Elle doit être complétée par une échographie Doppler artérielle devant des signes d'AOMI."},{"t":"Mesure isolée de la PO2 transcutanée, sans échographie Doppler","ok":false,"why":"Elle est prise en compte pour la décision chirurgicale, mais n'est pas l'examen de première intention."},{"t":"Aucune imagerie : l'examen clinique suffit à conclure","ok":false,"why":"Un ulcère de jambe justifie une échographie Doppler et la mesure de l'IPS."}],"explanation":"Devant un ulcère artériel, l'échographie Doppler artérielle avec IPS est l'examen de première intention ; l'angiographie est demandée en cas d'option chirurgicale.","src":"p. 325, 329, 338"},{"id":"d228-qru-103","type":"QRU","rank":"A","objective":"d228-obj-10","tags":["traitement"],"difficulty":2,"stem":"Un patient porteur d'un ulcère veineux a un IPS à 1,1. Quelle compression proposez-vous ?","options":[{"t":"Compression multicouche de 30 à 40 mmHg, toute la journée","ok":true,"why":"En l'absence d'AOMI, la compression à haut niveau de pression est recommandée."},{"t":"Compression inférieure à 30 mmHg avec bandes à étirement court","ok":false,"why":"C'est la compression adaptée de l'ulcère mixte à prédominance veineuse."},{"t":"Absence de compression en raison de l'œdème de la jambe","ok":false,"why":"La compression lutte contre l'œdème et est systématique."},{"t":"Compression nocturne uniquement, pour favoriser l'observance","ok":false,"why":"La compression doit être portée toute la journée."},{"t":"Repos strict au lit sans compression, jusqu'à cicatrisation","ok":false,"why":"La compression est systématique et une activité physique adaptée est recommandée."}],"explanation":"Ulcère veineux sans AOMI : compression systématique, à haut niveau de pression (30 à 40 mmHg), multicouche, portée toute la journée.","src":"p. 335"},{"id":"d228-qru-104","type":"QRU","rank":"A","objective":"d228-obj-15","tags":["complications","diagnostic"],"difficulty":2,"stem":"Un homme de 80 ans a un ulcère de jambe depuis des années, devenu douloureux, avec saignement local et bourgeonnement excessif. Quel diagnostic évoquer ?","options":[{"t":"Carcinome épidermoïde","ok":true,"why":"Chronicité, douleurs, hémorragie locale et bourgeonnement excessif y font penser ; il faut une biopsie."},{"t":"Colonisation bactérienne simple","ok":false,"why":"C'est un phénomène non pathologique qui ne change pas l'aspect de l'ulcère."},{"t":"Dermatite de contact","ok":false,"why":"Elle donne un érythème microvésiculeux prurigineux."},{"t":"Angiodermite nécrotique","ok":false,"why":"Elle débute brutalement par une plaque purpurique ou livedoïde évoluant vers une nécrose."},{"t":"Pyoderma gangrenosum","ok":false,"why":"Il débute par une pustule puis s'étend rapidement."}],"explanation":"Un ulcère chronique devenu douloureux, hémorragique, avec bourgeonnement excessif, doit faire évoquer un carcinome épidermoïde : biopsie, parfois répétée.","src":"p. 335"},{"id":"d228-qru-105","type":"QRU","rank":"A","objective":"d228-obj-15","tags":["complications","diagnostic"],"difficulty":1,"stem":"Une patiente porteuse d'un ulcère veineux, traité par de nombreux topiques, développe un érythème microvésiculeux prurigineux autour de l'ulcère. Quelle complication évoquer ?","options":[{"t":"Dermatite de contact","ok":true,"why":"Elle est fréquente en raison du grand nombre de topiques ; les tests épicutanés cherchent l'allergène."},{"t":"Surinfection bactérienne patente","ok":false,"why":"Elle se manifeste par une douleur accrue, une inflammation des bords, une lymphangite ou une fièvre."},{"t":"Carcinome épidermoïde","ok":false,"why":"Il est rare et tardif, avec chronicité, douleurs et bourgeonnement excessif."},{"t":"Hémorragie sur varice","ok":false,"why":"Elle correspond à un saignement d'une varice."},{"t":"Ankylose de la cheville","ok":false,"why":"C'est l'aboutissement des lésions ostéo-articulaires de l'ulcère."}],"explanation":"Un érythème microvésiculeux prurigineux sous topiques évoque une dermatite de contact ; on cherche l'allergène (baume du Pérou, antiseptiques, fragrances, lanoline, conservateurs, pansements).","src":"p. 334"},{"id":"d228-qru-106","type":"QRU","rank":"A","objective":"d228-obj-05","tags":["traitement"],"difficulty":2,"stem":"Dans l'ulcère artériel, dans quelle situation les analogues de la prostacycline sont-ils indiqués ?","options":[{"t":"Ischémie grave avec non-indication ou contre-indication chirurgicale","ok":true,"why":"C'est l'indication de la prostacycline."},{"t":"Ulcère artériel avec revascularisation possible, en première intention","ok":false,"why":"Le traitement étiologique chirurgical (pontage, dilatation, désobstruction) est alors privilégié."},{"t":"Ulcère mixte à prédominance veineuse","ok":false,"why":"Il se traite par prise en charge de l'AOMI et compression adaptée."},{"t":"Ulcère veineux avec reflux profond","ok":false,"why":"Il se traite par compression et, selon l'indication, chirurgie veineuse."},{"t":"Dermatite de contact péri-ulcéreuse","ok":false,"why":"Elle se traite par suppression de l'allergène et dermocorticoïdes."}],"explanation":"Traitement médical de l'ulcère artériel : vasodilatateurs et analogues de la prostacycline, ces derniers en cas d'ischémie grave sans possibilité chirurgicale ; chirurgie : désobstruction, pontage, sympathectomie.","src":"p. 336"},{"id":"d228-qru-107","type":"QRU","rank":"B","objective":"d228-obj-06","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Une femme de 70 ans, hypertendue et diabétique, présente brutalement une plaque purpurique livedoïde de la face antéro-externe de la jambe, évoluant vers une nécrose noirâtre puis des ulcérations en carte de géographie très douloureuses. Les pouls et l'échographie Doppler sont normaux. Quel est le diagnostic ?","options":[{"t":"Angiodermite nécrotique","ok":true,"why":"Infarctus cutané par occlusion artériolaire, avec grands axes artériels et veineux normaux."},{"t":"Ulcère veineux","ok":false,"why":"Il est périmalléolaire, moyennement douloureux, avec varices."},{"t":"Ulcère artériel par AOMI","ok":false,"why":"Il s'accompagne d'une abolition des pouls et d'une atteinte artérielle à l'échographie Doppler."},{"t":"Pyoderma gangrenosum","ok":false,"why":"Il débute par une pustule et forme des clapiers purulents avec un bourrelet violacé."},{"t":"Mal perforant plantaire","ok":false,"why":"C'est une ulcération neurologique indolore de la plante."}],"explanation":"Début brutal, plaque purpurique ou livedoïde, nécrose, ulcérations en carte de géographie, douleurs intenses, localisation antéro-externe et axes vasculaires normaux : angiodermite nécrotique.","src":"p. 331"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d228-pareto","points":[{"id":"d228-par-01","rank":"A","cat":"définition","text":"Ulcère de jambe = plaie ne cicatrisant pas depuis **> 1 mois** ; complication d'une **maladie vasculaire** sous-jacente (veineuse, artérielle, mixte) qui conditionne pronostic et traitement","src":"p. 326"},{"id":"d228-par-02","rank":"A","cat":"clinique","text":"Ulcère **veineux** : **femme** > 50 ans, ulcère unique, grand, moyennement douloureux, **périmalléolaire**, varices + œdème, dermite ocre, atrophie blanche, eczéma, lipodermatosclérose","src":"p. 327-329"},{"id":"d228-par-03","rank":"A","cat":"clinique","text":"Ulcère artériel : **homme** > 50 ans + FDR CV, ulcère creusant **distal/suspendu**, douleur intense (décubitus), peau lisse froide dépilée, **pouls abolis**","src":"p. 328-329"},{"id":"d228-par-04","rank":"A","cat":"examen","text":"Bilan : examen vasculaire complet + **écho-Doppler** veineux et/ou artériel + **IPS** ; écho-Doppler artériel si pouls abolis, signes d'AOMI ou **IPS < 0,9 ou > 1,3**","src":"p. 329, 331"},{"id":"d228-par-05","rank":"A","cat":"chiffre","text":"IPS **0,7-0,9** = ulcère **mixte** à prédominance veineuse ; IPS **> 1,3** = artères calcifiées incompressibles (diabète)","src":"p. 329, 331"},{"id":"d228-par-06","rank":"A","cat":"traitement","text":"Ulcère veineux : **compression systématique** à haut niveau (**30-40 mmHg**, multicouche, toute la journée) si IPS 0,8-1,3 ; **éveinage** si insuffisance veineuse superficielle sans reflux profond","src":"p. 335"},{"id":"d228-par-07","rank":"A","cat":"traitement","text":"Ulcère mixte : traiter l'**AOMI**, compression **< 30 mmHg** (IPS > 0,7), bandes à **étirement court**, sous surveillance médicale","src":"p. 336"},{"id":"d228-par-08","rank":"A","cat":"traitement","text":"Ulcère artériel : **chirurgie** (désobstruction, pontage, sympathectomie) selon écho-Doppler + angiographie ; **prostacycline** si ischémie grave non opérable ; amputation parfois","src":"p. 334, 336"},{"id":"d228-par-09","rank":"A","cat":"traitement","text":"Soins locaux selon 3 phases : **détersion** (douchette, alginates/hydrogels, pas d'antiseptique), **bourgeonnement** (tulles, hydrocolloïdes), **épidermisation** (greffes si > 10 cm² ou > 6 mois)","src":"p. 337"},{"id":"d228-par-10","rank":"A","cat":"gravité","text":"Complications : **dermatite de contact** (baume du Pérou, tests épicutanés), **surinfection** (douleur ↑, lymphangite, fièvre), **carcinome épidermoïde** (chronicité, bourgeonnement excessif → biopsie)","src":"p. 334-335"},{"id":"d228-par-11","rank":"A","cat":"piège","text":"**Colonisation** ≠ infection : ni prélèvement ni antiseptique/antibiotique systématiques ; **vaccination antitétanique** à vérifier (+++)","src":"p. 334, 336"},{"id":"d228-par-12","rank":"A","cat":"suivi","text":"Pronostic : cicatrisation en **3-6 mois** (ulcère variqueux), récidives fréquentes ; ulcère **post-thrombotique** = le plus rebelle","src":"p. 333, 338"},{"id":"d228-par-13","rank":"A","cat":"clinique","text":"**Douleur de décubitus** + **extension nécrotique** = orientation vers une cause **artérielle** ou artériolaire (angiodermite nécrotique)","src":"p. 338"},{"id":"d228-par-14","rank":"A","cat":"prévention","text":"Traitement général : **arrêt du tabac**, équilibre diabète/HTA/lipides, perte de poids, antalgiques avant les soins, activité physique adaptée, évaluation nutritionnelle","src":"p. 336"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
